        while (i < n) {
            if (i + 2 < n && s[i + 2] == '#') {
                res += char('a' + stoi(s.substr(i, 2)) - 1);
                i += 3;
            } else {
                res += char('a' + (s[i] - '0') - 1);
                i += 1;
            }
        }
        return res;
